style.css:
@-moz-document domain("roblox.com") {
/* Targets the main background container on Roblox */
    body, 
    .content, 
    #container-main,
    .dark-theme,
    .light-theme,
    .gandalf-theme,
    .container-main {
        background-image: url("https://gstatic.com") !important;
        background-color: transparent !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center center !important;
        background-size: cover !important;
    }

    /* Makes the white/dark content blocks transparent so you can see your image */
    .section-content,
    .mcl-container,
    .section,
    .container-list,
    .rbx-tab-content {
        background-color: rgba(255, 255, 255, 0.05) !important;
        backdrop-filter: blur(2px) !important;
    }
}
